input.oldString:
@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
	html {
		scroll-behavior: smooth;
	}

	body {
		@apply bg-white text-secondary-900;
	}
}

@layer components {
	.btn-primary {
		@apply inline-flex items-center justify-center px-6 py-3 text-base font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-700 transition-colors shadow-lg;
	}

	.btn-secondary {
		@apply inline-flex items-center justify-center px-6 py-3 text-base font-medium text-primary-600 bg-primary-50 rounded-lg hover:bg-primary-100 transition-colors border border-primary-200;
	}

	.card {
		@apply bg-white rounded-xl border border-secondary-200 hover:shadow-xl transition-all duration-300;
	}

	.card-hover {
		@apply hover:border-primary-300 hover:shadow-xl transition-all duration-300;
	}
}

/* Custom animations */
@keyframes fadeIn {
	from {
		opacity: 0;
		transform: translateY(20px);
	}
	to {
		opacity: 1;
		transform: translateY(0);
	}
}

.animate-fade-in {
	animation: fadeIn 0.6s ease-out;
}

/* Focus styles for accessibility */
.focus-ring {
	@apply focus:outline-none focus:ring-2 focus:ring-primary-500 focus:ring-offset-2;
}

/* Smooth transitions */
.transition-smooth {
	@apply transition-all duration-300 ease-in-out;
}

/* Custom scrollbar */
::-webkit-scrollbar {
	width: 8px;
}

::-webkit-scrollbar-track {
	@apply bg-secondary-100;
}

::-webkit-scrollbar-thumb {
	@apply bg-secondary-300 rounded-full;
}

::-webkit-scrollbar-thumb:hover {
	@apply bg-secondary-400;
}

input.newString:
@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
	html {
		scroll-behavior: smooth;
	}

	body {
		@apply bg-white text-secondary-900 transition-colors duration-300;
	}

	.dark body {
		@apply bg-dark-bg text-dark-text;
	}
}

@layer components {
	.btn-primary {
		@apply inline-flex items-center justify-center px-6 py-3 text-base font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-700 transition-colors shadow-lg;
	}

	.btn-secondary {
		@apply inline-flex items-center justify-center px-6 py-3 text-base font-medium text-primary-600 bg-primary-50 rounded-lg hover:bg-primary-100 transition-colors border border-primary-200;
	}

	.dark .btn-secondary {
		@apply text-primary-400 bg-primary-900/20 hover:bg-primary-900/30 border-primary-800;
	}

	.card {
		@apply bg-white rounded-xl border border-secondary-200 hover:shadow-xl transition-all duration-300;
	}

	.dark .card {
		@apply bg-dark-surface border-dark-border;
	}

	.card-hover {
		@apply hover:border-primary-300 hover:shadow-xl transition-all duration-300;
	}

	.dark .card-hover {
		@apply hover:border-primary-600;
	}

	.nav-header {
		@apply bg-white/80 backdrop-blur-md border-b border-secondary-200;
	}

	.dark .nav-header {
		@apply bg-dark-surface/90 border-dark-border;
	}

	.footer-section {
		@apply bg-secondary-50 border-t border-secondary-200;
	}

	.dark .footer-section {
		@apply bg-dark-surface border-dark-border;
	}

	.hero-gradient {
		@apply bg-gradient-to-br from-primary-50 via-white to-secondary-50;
	}

	.dark .hero-gradient {
		@apply bg-gradient-dark;
	}

	.stats-section {
		@apply bg-white border-b border-secondary-200;
	}

	.dark .stats-section {
		@apply bg-dark-surface border-dark-border;
	}

	.featured-section {
		@apply bg-secondary-50;
	}

	.dark .featured-section {
		@apply bg-dark-surface;
	}

	.input-field {
		@apply bg-white border-secondary-300 text-secondary-900 placeholder-secondary-500;
	}

	.dark .input-field {
		@apply bg-dark-surface border-dark-border text-dark-text placeholder-dark-textSecondary;
	}
}

/* Custom animations */
@keyframes fadeIn {
	from {
		opacity: 0;
		transform: translateY(20px);
	}
	to {
		opacity: 1;
		transform: translateY(0);
	}
}

.animate-fade-in {
	animation: fadeIn 0.6s ease-out;
}

/* Focus styles for accessibility */
.focus-ring {
	@apply focus:outline-none focus:ring-2 focus:ring-primary-500 focus:ring-offset-2;
}

.dark .focus-ring {
	@apply focus:ring-offset-dark-surface;
}

/* Smooth transitions */
.transition-smooth {
	@apply transition-all duration-300 ease-in-out;
}

/* Custom scrollbar */
::-webkit-scrollbar {
	width: 8px;
}

::-webkit-scrollbar-track {
	@apply bg-secondary-100 dark:bg-dark-surface;
}

::-webkit-scrollbar-thumb {
	@apply bg-secondary-300 dark:bg-dark-border rounded-full;
}

::-webkit-scrollbar-thumb:hover {
	@apply bg-secondary-400 dark:bg-secondary-600;
}

/* Dark mode transitions */
* {
	transition-property: background-color, border-color, color;
	transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
	transition-duration: 200ms;
}

